AP4_HdlrAtom::AP4_HdlrAtom(AP4_UI32 size, AP4_UI08 version, AP4_UI32 flags, AP4_ByteStream& stream) :
    AP4_Atom(AP4_ATOM_TYPE_HDLR, size, version, flags)
{
    AP4_UI32  pre_defined[3];
    AP4_UI32  handler_type;
    AP4_UI32  reserved[2];

    stream.ReadBE(pre_defined, sizeof(pre_defined));
    stream.ReadBE(&handler_type, sizeof(handler_type));
    stream.ReadBE(reserved, sizeof(reserved));

    m_HandlerType = handler_type;

    // read the name
    AP4_Size name_size = m_Size - (stream.Tell() - ((m_Size - m_DataSize) ? m_Size - m_DataSize : 0));
    if (name_size > 0) {
        AP4_UI08 name_length;
        stream.ReadBE(&name_length);
        if (name_length > 0) {
            AP4_String name;
            name.SetLength(name_length);
            stream.ReadBE(name.UseBuffer(), name_length);
            // handle Pascal string
            m_Name = name;
        } else {
            // handle C string
            AP4_Size available = name_size;
            AP4_String name;
            AP4_Result result = stream.ReadString(name, available);
            if (AP4_SUCCEEDED(result)) {
                m_Name = name;
            }
        }
    }
}

AP4_HdlrAtom::AP4_HdlrAtom(AP4_UI32 size, AP4_UI08 version, AP4_UI32 flags, AP4_ByteStream& stream)
    : AP4_Atom(AP4_ATOM_TYPE_HDLR, size, version, flags)
{
    AP4_UI32  pre_defined;
    AP4_UI32  handler_type;
    AP4_UI32  reserved[2];
    AP4_UI16  name_length;

    // read the fixed part of the atom
    stream.ReadBEUI32(pre_defined);
    stream.ReadBEUI32(handler_type);
    stream.ReadBEUI32(reserved[0]);
    stream.ReadBEUI32(reserved[1]);

    // read the handler name
    stream.ReadBEUI16(name_length);
    if (name_length > 0) {
        if (name_length > (m_size - (stream.Tell() - m_start_position))) {
            name_length = m_size - (stream.Tell() - m_start_position);
        }

        AP4_UI08* name = new AP4_UI08[name_length + 1];
        stream.Read(name, name_length);
        name[name_length] = 0; // null-terminate

        // check if the name is a Pascal string
        if (name[0] == 0) {
            AP4_UI08* pascal_name = new AP4_UI08[name_length + 1];
            AP4_UI08 pascal_length = name[0];
            if (pascal_length > name_length) {
                pascal_length = name_length;
            }
            memcpy(pascal_name, &name[1], pascal_length);
            pascal_name[pascal_length] = 0; // null-terminate
            m_handler_name = AP4_String((char*)pascal_name);
            delete[] pascal_name;
        }
        else {
            m_handler_name = AP4_String((char*)name);
        }
        delete[] name;
    }
}

AP4_HdlrAtom::AP4_HdlrAtom(AP4_UI32 size, AP4_UI08 version, AP4_UI32 flags, AP4_ByteStream& stream)
    : AP4_Atom(AP4_ATOM_TYPE_HDLR, size, version, flags)
{
    AP4_UI32  pre_defined;
    AP4_UI32  handler_type;
    AP4_UI32  reserved[3];
    AP4_UI08  name_size;

    // Read the predefined values and handler type
    stream.ReadBE(pre_defined);
    stream.ReadBE(handler_type);
    stream.ReadBE(reserved, 3);

    // Skip reserved bytes
    stream.Skip(3 * sizeof(AP4_UI32));

    // Read the name size
    stream.ReadBE(name_size);

    // Check if there is space for a name
    if (name_size > 0) {
        AP4_Size available = GetSize() - (stream.Tell() - (AP4_Size)((AP4_ByteStream*)(&stream)->GetLocation()));
        if (name_size <= available) {
            AP4_String name;
            if (name_size == 1) {
                // Pascal string
                AP4_UI08 len;
                stream.ReadBE(len);
                name.SetLength(len);
                stream.ReadBE(name.GetChars(), len);
            } else {
                // C string
                name.Resize(name_size - 1);
                stream.ReadBE(name.GetChars(), name_size - 1);
            }
            m_name = name;
        }
    }
}

AP4_HdlrAtom::AP4_HdlrAtom(AP4_UI32 size, AP4_UI08 version, AP4_UI32 flags, AP4_ByteStream& stream) :
    AP4_Atom(AP4_ATOM_TYPE_HDLR, size, version, flags)
{
    AP4_UI32  pre_defined[3];
    AP4_UI32  handler_type;
    AP4_UI32  reserved[2];
    AP4_Size  name_size = m_Size - (4 + 1 + 4*3 + 4 + 2*4);

    // read the data
    stream.ReadBytes(pre_defined,     sizeof(pre_defined));
    stream.ReadBytes(&handler_type,   sizeof(handler_type));
    stream.ReadBytes(reserved,        sizeof(reserved));

    if (name_size > 0) {
        AP4_String name;
        AP4_UI08 prefix;

        stream.Read(&prefix);
        if (prefix == 0) {
            // C string
            AP4_Size max_length = name_size;
            AP4_String value;
            value.SetLength(max_length);
            stream.ReadBytes((AP4_Byte*)value.UseData(), max_length);
            name = value;
        } else {
            // Pascal string
            AP4_UI08 length = prefix;
            AP4_String value;
            value.SetLength(length);
            stream.ReadBytes((AP4_Byte*)value.UseData(), length);
            name = value;
        }
        m_Name = name;
    }
}

AP4_HdlrAtom::AP4_HdlrAtom(AP4_UI32 size, AP4_UI08 version, AP4_UI32 flags, AP4_ByteStream& stream) :
    AP4_Atom(AP4_ATOM_TYPE_HDLR, size, version, flags)
{
    AP4_UI32  predefined;
    AP4_UI32  handler_type;
    AP4_UI16  reserved[3];
    AP4_UI16  name_length;

    // read the handler info
    stream.ReadBE((AP4_UI08*)&predefined, sizeof(predefined));
    stream.ReadBE((AP4_UI08*)&handler_type, sizeof(handler_type));
    stream.ReadBE((AP4_UI08*)reserved, sizeof(reserved));

    // read the name
    stream.ReadBE((AP4_UI08*)&name_length, sizeof(name_length));
    if (name_length > 0) {
        if (name_length > (size - (4 + 4 + 12))) {
            // invalid length, cap it to the remaining size
            name_length = size - (4 + 4 + 12);
        }
        m_name.SetLength(name_length);
        stream.ReadBE((AP4_UI08*)m_name.UseData(), name_length);
        // ensure null-termination if the string is not already null-terminated
        if (m_name[name_length - 1] != '\0') {
            m_name.Append('\0');
        }
        // handle Pascal-style strings (first byte is length)
        if (name_length > 0 && m_name[0] < name_length) {
            AP4_UI08 length = m_name[0];
            if (length < name_length) {
                m_name.SetLength(length + 1);
                m_name[length + 1] = '\0';
            }
        }
    }
}
